result.coinSilver = coinSilver ? { type: coinSilver.type, width: coinSilver.width, height: coinSilver.height } : null;
result.coinPlatinum = coinPlatinum ? { type: coinPlatinum.type, width: coinPlatinum.width, height: coinPlatinum.height } : null;

// Get articles
const art1 = await figma.getNodeByIdAsync("5:55");
const art2 = await figma.getNodeByIdAsync("5:60");
const notif1 = await figma.getNodeByIdAsync("5:65");
const notif2 = await figma.getNodeByIdAsync("5:70");
result.article1 = art1 ? { type: art1.type, width: art1.width, height: art1.height } : null;
result.article2 = art2 ? { type: art2.type, width: art2.width, height: art2.height } : null;
result.notifApple = notif1 ? { type: notif1.type, width: notif1.width, height: notif1.height } : null;
result.notifNextAges = notif2 ? { type: notif2.type, width: notif2.width, height: notif2.height } : null;

// Get bank logos
const boa = await figma.getNodeByIdAsync("5:78");
const zenith = await figma.getNodeByIdAsync("5:83");
result.boa = boa ? { type: boa.type, width: boa.width, height: boa.height } : null;
result.zenith = zenith ? { type: zenith.type, width: zenith.width, height: zenith.height } : null;

return JSON.stringify(result, null, 2);

