// Get image hashes from all raster assets so we can reuse them
const assets = {};
const ids = {
  logo: "5:17",
  welcomeIllust: "5:22",
  coinGold: "5:37",
  coinSilver: "5:42",
  coinPlatinum: "5:47",
  article1: "5:55",
  article2: "5:60",
  notifApple: "5:65",
  notifNextAges: "5:70",
  boa: "5:78",
  zenith: "5:83",
};
for (const [key, id] of Object.entries(ids)) {
  const node = await figma.getNodeByIdAsync(id);
  if (node && node.fills && node.fills[0] && node.fills[0].imageHash) {
    assets[key] = node.fills[0].imageHash;
  }
}

// Get avatar ellipses
const av = await figma.getNodeByIdAsync("5:27");
if (av) {
  assets.avatarChildren = av.children.map(c => ({
    id: c.id, type: c.type, name: c.name,
    x: c.x, y: c.y, width: c.width, height: c.height,
    fills: c.fills,
    cornerRadius: c.cornerRadius,
  }));
  assets.avatarFills = av.fills;
  assets.avatarCornerRadius = av.cornerRadius;
}

// Get icon components
const iconIds = ["6:269","6:270","6:271","6:272","6:273","6:274","6:275","6:276","6:277","6:278","6:279","6:280","6:281","6:282","6:283","6:284","6:285"];
assets.icons = {};
for (const id of iconIds) {
  const node = await figma.getNodeByIdAsync(id);
  if (node) {
    assets.icons[node.name] = { id, width: node.width, height: node.height };
  }
}

// Get text field inner structure
const tf = await figma.getNodeByIdAsync("6:23");
if (tf && tf.children && tf.children[0]) {
  const field = tf.children[0];
  assets.textFieldInner = {
    fills: field.fills,
    cornerRadius: field.cornerRadius,
    strokes: field.strokes,
    strokeWeight: field.strokeWeight,
    children: field.children ? field.children.map(c => ({
      id: c.id, type: c.type, name: c.name,
      x: c.x, y: c.y, width: c.width, height: c.height,
      characters: c.characters || null,
      fills: c.fills,
      fontSize: c.fontSize,
      fontName: c.fontName,
      opacity: c.opacity,
    })) : null,
  };
}

// Get button label details
const btn = await figma.getNodeByIdAsync("6:7");
if (btn && btn.children && btn.children[0]) {
  const label = btn.children[0];
  assets.buttonLabel = {
    characters: label.characters,
    fontSize: label.fontSize,
    fontName: label.fontName,
    fills: label.fills,
    x: label.x, y: label.y,
  };
}

return JSON.stringify(assets, null, 2);

