// Helper: create a rectangle with image fill
function imageRect(hash, w, h, scaleMode = "FIT") {
  const r = figma.createRectangle();
  r.resize(w, h);
  r.fills = [{ type: "IMAGE", imageHash: hash, scaleMode: scaleMode }];
  return r;
}

// Helper: create text
function txt(chars, fontFamily, fontStyle, fontSize, color, lineHeight) {
  const t = figma.createText();
  t.fontName = { family: fontFamily, style: fontStyle };
  t.characters = chars;
  t.fontSize = fontSize;
  t.fills = [{ type: "SOLID", color: color }];
  if (lineHeight) t.lineHeight = { value: lineHeight, unit: "PIXELS" };
  return t;
}

// Helper: rounded rect
function rect(w, h, color, cornerRadius) {
  const r = figma.createRectangle();
  r.resize(w, h);
  if (color) r.fills = [{ type: "SOLID", color: color }];
  if (cornerRadius) r.cornerRadius = cornerRadius;
  return r;
}

// Helper: ellipse
function ellipse(w, h, color) {
  const e = figma.createEllipse();
  e.resize(w, h);
  if (color) e.fills = [{ type: "SOLID", color: color }];
  return e;
}

