// Helper to create a create-account screen
async function createAccountScreen(name, x, state) {
  const frame = figma.createFrame();
  frame.name = name;
  frame.resize(414, 932);
  frame.fills = [{ type: "SOLID", color: C.white }];
  frame.x = x;
  frame.y = 0;
  frame.clipsContent = true;

  // Status bar
  const sb = statusBar.createInstance();
  sb.x = 0; sb.y = 0;
  frame.appendChild(sb);

  // Home indicator
  const hi = homeInd.createInstance();
  hi.x = 0; hi.y = 932 - 34;
  frame.appendChild(hi);

  // Back button
  const backBtn = figma.createFrame();
  backBtn.name = "Back";
  backBtn.resize(40, 40);
  backBtn.cornerRadius = 12;
  backBtn.fills = [{ type: "SOLID", color: C.bg }];
  backBtn.x = 24; backBtn.y = 60;
  frame.appendChild(backBtn);

  const backIcon = iconBack.createInstance();
  backIcon.x = 16; backIcon.y = 13;
  backBtn.appendChild(backIcon);

  // Title
  const title = txt("Create an account", "DM Sans", "Bold", 28, C.textPrimary);
  title.x = 30; title.y = 130;
  frame.appendChild(title);

  // Subtitle
  const subtitle = txt("Invest and double your income now", "Inter", "Regular", 15, C.textSecondary);
  subtitle.x = 30; subtitle.y = 172;
  frame.appendChild(subtitle);

  // Email field
  const emailField = tfComp.createInstance();
  emailField.x = 30; emailField.y = 220;
  const emailValue = emailField.findOne(n => n.name === "Value");
  if (state === "empty") {
    if (emailValue) emailValue.characters = "Email address";
  } else if (state === "filled") {
    if (emailValue) { emailValue.characters = "jonas.macroni@invest.ai"; emailValue.fills = [{ type: "SOLID", color: C.textPrimary }]; }
  } else if (state === "error") {
    if (emailValue) { emailValue.characters = "jonas.macroni@invest"; emailValue.fills = [{ type: "SOLID", color: C.textPrimary }]; }
    // Error state: red border
    const fieldInner = emailField.findOne(n => n.name === "Field");
    if (fieldInner) {
      fieldInner.strokes = [{ type: "SOLID", color: C.error }];
      fieldInner.strokeWeight = 1.5;
    }
  }
  frame.appendChild(emailField);

  // Full name field
  const nameField = tfComp.createInstance();
  nameField.x = 30; nameField.y = 296;
  const nameValue = nameField.findOne(n => n.name === "Value");
  if (state === "empty") {
    if (nameValue) nameValue.characters = "Full name";
  } else {
    if (nameValue) { nameValue.characters = "Jonas Macroni"; nameValue.fills = [{ type: "SOLID", color: C.textPrimary }]; }
  }
  frame.appendChild(nameField);

  // Password field
  const pwField = tfComp.createInstance();
  pwField.x = 30; pwField.y = 372;
  const pwValue = pwField.findOne(n => n.name === "Value");
  if (state === "empty") {
    if (pwValue) pwValue.characters = "Password";
  } else {
    if (pwValue) { pwValue.characters = "••••••••••"; pwValue.fills = [{ type: "SOLID", color: C.textPrimary }]; }
  }
  frame.appendChild(pwField);

  // Error message for error state
  if (state === "error") {
    const errorMsg = txt("Enter a valid email address", "Inter", "Regular", 13, C.error);
    errorMsg.x = 30; errorMsg.y = 448;
    frame.appendChild(errorMsg);
  }

  // Create account button
  const btn = btnComp.createInstance();
  btn.x = 30;
  btn.y = state === "error" ? 486 : 460;
  const lbl = btn.findOne(n => n.name === "Label");
  if (lbl) lbl.characters = "Create account";
  if (state === "empty") {
    // Disabled state
    btn.opacity = 0.4;
  }
  frame.appendChild(btn);

  // "Already have an account?" text
  const haveAcct = txt("Already have an account? ", "Inter", "Regular", 14, C.textSecondary);
  const loginLink = txt("Login", "Inter", "Semi Bold", 14, C.primary);
  haveAcct.x = 30;
  haveAcct.y = btn.y + 76;
  frame.appendChild(haveAcct);
  loginLink.x = 30 + haveAcct.width;
  loginLink.y = haveAcct.y;
  frame.appendChild(loginLink);

  page.appendChild(frame);
  return frame.id;
}

