};

const results = [];

// Helper to add reaction
async function addLink(sourceId, targetId, trigger = "ON_CLICK") {
  const source = await figma.getNodeByIdAsync(sourceId);
  const target = await figma.getNodeByIdAsync(targetId);
  if (source && target) {
    source.reactions = [{
      trigger: { type: trigger },
      actions: [{
        type: "NODE",
        destinationId: target.id,
        navigation: "NAVIGATE",
        transition: trigger === "ON_CLICK" ? null : { type: "DISSOLVE", duration: 0.3, easing: "EASE_OUT" },
      }],
    }];
    return true;
  }
  return false;
}

// Helper to add overlay link
async function addOverlayLink(sourceId, targetId) {
  const source = await figma.getNodeByIdAsync(sourceId);
  const target = await figma.getNodeByIdAsync(targetId);
  if (source && target) {
    source.reactions = [{
      trigger: { type: "ON_CLICK" },
      actions: [{
        type: "NODE",
        destinationId: target.id,
        navigation: "OPEN_OVERLAY",
        transition: { type: "MOVE_IN", direction: "BOTTOM", duration: 0.3, easing: "EASE_OUT" },
        overlayPosition: { type: "BOTTOM_CENTER" },
        overlayBackground: { type: "SOLID_COLOR", color: { r: 0, g: 0, b: 0 }, opacity: 0.4 },
      }],
    }];
    return true;
  }
  return false;
}

// Helper to add back link (close overlay)
async function addBackLink(sourceId, targetId) {
  const source = await figma.getNodeByIdAsync(sourceId);
  const target = await figma.getNodeByIdAsync(targetId);
  if (source && target) {
    source.reactions = [{
      trigger: { type: "ON_CLICK" },
      actions: [{
        type: "NODE",
        destinationId: target.id,
        navigation: "NAVIGATE",
        transition: null,
      }],
    }];
    return true;
  }
  return false;
}

// 1. Splash → Welcome (auto-advance)
