function txt(chars, fontFamily, fontStyle, fontSize, color) {
  const t = figma.createText();
  t.fontName = { family: fontFamily, style: fontStyle };
  t.characters = chars;
  t.fontSize = fontSize;
  t.fills = [{ type: "SOLID", color: color }];
  return t;
}
function rect(w, h, color, cornerRadius) {
  const r = figma.createRectangle();
  r.resize(w, h);
  if (color) r.fills = [{ type: "SOLID", color: color }];
  if (cornerRadius) r.cornerRadius = cornerRadius;
  return r;
}

