const notif = await figma.getNodeByIdAsync("2016:2");
const emoji = notif.children.find(n => n.type === "TEXT" && n.characters === "👤");
if (emoji) emoji.remove();

// Clone Avatar_Neutral into the notification
const avatarNode = await figma.getNodeByIdAsync("5:27");
const avatarClone = avatarNode.clone();
avatarClone.resize(40, 40);
// scale children proportionally
const scale = 40 / 150;
avatarClone.children.forEach(c => {
  c.x = c.x * scale;
  c.y = c.y * scale;
  c.resize(c.width * scale, c.height * scale);
});
avatarClone.x = 24 + 12;
avatarClone.y = 258 + 12;
avatarClone.clipsContent = true;
notif.appendChild(avatarClone);
return "Avatar placed in notification";

// Fix 05_My_Asset_Overlay: make the frame itself fill 414x932 with transparent fills
// and ensure the Sheet has proper top-rounded corners
const overlay = await figma.getNodeByIdAsync("2015:2");
// The frame should have no fill (transparent) so Home shows through
overlay.fills = [];

// The Sheet should only be visible in the bottom portion
const sheet = overlay.findOne(n => n.name === "Sheet");
if (sheet) {
  sheet.clipsContent = true;
  sheet.topLeftRadius = 24;
  sheet.topRightRadius = 24;
  sheet.bottomLeftRadius = 0;
  sheet.bottomRightRadius = 0;
}

return "Overlay fixed";

