// Final check: verify all 11 frames exist with correct names
const page = await figma.getNodeByIdAsync("2004:2");
const frameNames = page.children
  .filter(n => n.type === "FRAME")
  .map(n => ({ id: n.id, name: n.name, x: Math.round(n.x), y: Math.round(n.y) }));
